+  });
+
+  it('should handle duplicates', function() {
+    var parsed = parseHeaders(
+      'Age: age-a\n' + // age is in ignore duplicates blacklist
+      'Age: age-b\n' +
+      'Foo: foo-a\n' +
+      'Foo: foo-b\n'
+    );
+
+    expect(parsed['age']).toEqual('age-a');
